335	private struct ChargingRemainingText: View {
336	    var estimatedFullAt: Date?
337	
338	    var body: some View {
339	        TimelineView(.periodic(from: Date(), by: 30)) { context in
340	            Text(remainingText(now: context.date))
341	        }
342	    }
343	
344	    private func remainingText(now: Date) -> String {
345	        guard let estimatedFullAt else { return "--" }
346	        let remainingSeconds = estimatedFullAt.timeIntervalSince(now)
347	        guard remainingSeconds > 0 else { return "0分" }
348	
349	        let totalMinutes = max(Int(ceil(remainingSeconds / 60)), 1)
350	        let hours = totalMinutes / 60
351	        let minutes = totalMinutes % 60
352	
353	        if hours > 0 {
354	            return "\(hours):\(String(format: "%02d", minutes))"
355	        }
356	        return "\(minutes)分"
357	    }
358	}
