420	private func chargingCardGradient(for colorScheme: ColorScheme) -> LinearGradient {
421	    if colorScheme == .dark {
422	        return LinearGradient(
423	            colors: [
424	                Color(red: 0.07, green: 0.08, blue: 0.11),
425	                Color(red: 0.045, green: 0.08, blue: 0.075),
426	                Color(red: 0.055, green: 0.11, blue: 0.085)
427	            ],
428	            startPoint: .topLeading,
429	            endPoint: .bottomTrailing
430	        )
431	    }
432	
433	    return LinearGradient(
434	        colors: [
435	            Color(red: 0.96, green: 0.90, blue: 1.0),
436	            Color(red: 0.91, green: 0.96, blue: 1.0),
437	            Color(red: 0.82, green: 1.0, blue: 0.96)
438	        ],
439	        startPoint: .topLeading,
440	        endPoint: .bottomTrailing
441	    )
442	}
