577	private struct SmallWidgetBatteryRing: View {
578	    var value: Double
579	    var battery: Int?
580	    var isCharging: Bool
581	    @Environment(\.colorScheme) private var colorScheme
582	
583	    var body: some View {
584	        ZStack {
585	            Circle()
586	                .stroke(smallWidgetRingTrack(for: colorScheme), lineWidth: 5)
587	
588	            Circle()
589	                .trim(from: 0, to: min(max(value, 0), 1))
590	                .stroke(activeColor, style: StrokeStyle(lineWidth: 5, lineCap: .round))
591	                .rotationEffect(.degrees(-90))
592	
593	            if isCharging {
594	                Image(systemName: "bolt.fill")
595	                    .font(.system(size: 9, weight: .bold))
596	                    .foregroundStyle(WidgetTheme.green)
597	            } else {
598	                Circle()
599	                    .fill(smallWidgetBackground(for: colorScheme))
600	                    .frame(width: 12, height: 12)
601	            }
602	        }
603	    }
604	
605	    private var activeColor: Color {
606	        if isCharging { return WidgetTheme.green }
607	        guard let battery else { return WidgetTheme.green }
608	        return battery < 20 ? .red : WidgetTheme.green
609	    }
610	}
