1240	private func batteryColor(_ value: Int?, isCharging: Bool = false) -> Color {
1241	    if isCharging { return WidgetTheme.green }
1242	    guard let value else { return .gray }
1243	    if value < 15 { return .red }
1244	    if value < 50 { return .orange }
1245	    return WidgetTheme.green
1246	}
