1248	private func healthColor(_ level: NinebotVehicleHealthLevel) -> Color {
1249	    switch level {
1250	    case .good:
1251	        return WidgetTheme.green
1252	    case .attention:
1253	        return .orange
1254	    case .critical:
1255	        return .red
1256	    case .charging:
1257	        return WidgetTheme.green
