79	private enum NinebotWidgetIntentRunner {
80	    private static let refreshSession: URLSession = {
81	        let configuration = URLSessionConfiguration.ephemeral
82	        configuration.timeoutIntervalForRequest = 8
83	        configuration.timeoutIntervalForResource = 12
84	        configuration.requestCachePolicy = .reloadIgnoringLocalCacheData
85	        return URLSession(configuration: configuration)
86	    }()
87	
88	    static func refreshDashboard() async throws -> String {
89	        let startedAt = Date()
90	        let store = NinebotSharedStore()
91	        do {
92	            let client = try client(from: store)
93	            let cached = store.loadDashboard()
94	            let dashboard = try await client.fetchDashboard(selectedSN: cached?.selectedSN)
95	            let archivedDashboard = store.saveDashboard(dashboard)
96	            recordWidgetEvent(store: store, startedAt: startedAt, operation: "刷新车况", success: true, message: archivedDashboard.primaryVehicle?.vehicle.name)
97	            WidgetCenter.shared.reloadAllTimelines()
98	            return archivedDashboard.primaryVehicle?.vehicle.name ?? "九号"
99	        } catch {
100	            recordWidgetEvent(store: store, startedAt: startedAt, operation: "刷新车况", success: false, message: error.localizedDescription)
101	            throw error
102	        }
103	    }
104	
105	    static func perform(_ action: NinebotWidgetVehicleAction) async throws -> String {
106	        let startedAt = Date()
107	        let store = NinebotSharedStore()
108	        do {
109	            let client = try client(from: store)
110	            let dashboard = try await dashboardForOperation(store: store, client: client)
111	            guard let vehicle = dashboard.primaryVehicle?.vehicle else {
112	                throw NinebotWidgetIntentError.missingVehicle
113	            }
114	
115	            switch action {
116	            case .bell:
117	                _ = try await client.ringBell(sn: vehicle.sn)
118	            case .openBucket:
119	                _ = try await client.openBucket(sn: vehicle.sn)
120	            case .engineStart:
121	                _ = try await client.engineStart(sn: vehicle.sn)
122	            case .engineStop:
123	                _ = try await client.engineStop(sn: vehicle.sn)
124	            }
125	
126	            let refreshed = try await client.fetchDashboard(selectedSN: vehicle.sn)
127	            store.saveDashboard(refreshed)
128	            recordWidgetEvent(store: store, startedAt: startedAt, operation: action.title, success: true, message: vehicle.name)
129	            WidgetCenter.shared.reloadAllTimelines()
130	            return vehicle.name
131	        } catch {
132	            recordWidgetEvent(store: store, startedAt: startedAt, operation: action.title, success: false, message: error.localizedDescription)
133	            throw error
134	        }
135	    }
136	
137	    private static func client(from store: NinebotSharedStore) throws -> NinebotServerClient {
138	        let configuration = store.loadConfiguration() ?? NinebotServerConfiguration(baseURLString: "", bearerToken: "")
139	        guard configuration.isUsable else {
140	            throw NinebotWidgetIntentError.missingConfiguration
141	        }
142	        return NinebotServerClient(configuration: configuration, session: refreshSession)
143	    }
144	
145	    private static func dashboardForOperation(
146	        store: NinebotSharedStore,
147	        client: NinebotServerClient
148	    ) async throws -> NinebotDashboard {
149	        if let cached = store.loadDashboard(), cached.primaryVehicle != nil {
150	            return cached
151	        }
152	
153	        let dashboard = try await client.fetchDashboard(selectedSN: nil)
154	        let archivedDashboard = store.saveDashboard(dashboard)
155	        guard archivedDashboard.primaryVehicle != nil else {
156	            throw NinebotWidgetIntentError.missingVehicle
157	        }
158	        return archivedDashboard
159	    }
160	
161	    private static func recordWidgetEvent(
162	        store: NinebotSharedStore,
163	        startedAt: Date,
164	        operation: String,
165	        success: Bool,
166	        message: String?
167	    ) {
168	        store.saveLastWidgetRefreshEvent(NinebotRefreshEvent(
169	            source: "Widget",
170	            operation: operation,
171	            startedAt: startedAt,
172	            endedAt: Date(),
173	            success: success,
174	            message: message
175	        ))
176	    }
177	}
