180	    case missingConfiguration
181	    case missingVehicle
182	
183	    var errorDescription: String? {
184	        switch self {
185	        case .missingConfiguration:
186	            return "请先在 App 里配置数据源"
187	        case .missingVehicle:
188	            return "没有找到可操作的车辆"
189	        }
190	    }
191	}
