119	@available(iOS 16.1, *)
120	@MainActor
121	private final class NinebotChargingLiveActivityTokenObserver {
122	    static let shared = NinebotChargingLiveActivityTokenObserver()
123	
124	    private let store = NinebotSharedStore()
125	    private var pushToStartTask: Task<Void, Never>?
126	    private var activityUpdatesTask: Task<Void, Never>?
127	    private var activityTokenTasks: [String: Task<Void, Never>] = [:]
128	
129	    func start() {
130	        guard ActivityAuthorizationInfo().areActivitiesEnabled else { return }
131	        observeExistingActivities()
132	        observeActivityUpdates()
133	        observePushToStartToken()
134	    }
135	
136	    func observeActivity(_ activity: Activity<NinebotChargingActivityAttributes>) {
137	        if let token = activity.pushToken {
138	            registerActivityPushToken(token, activity: activity)
139	        }
140	
141	        guard activityTokenTasks[activity.id] == nil else { return }
142	        activityTokenTasks[activity.id] = Task { [weak self] in
143	            for await tokenData in activity.pushTokenUpdates {
144	                self?.registerActivityPushToken(tokenData, activity: activity)
145	            }
146	        }
147	    }
148	
149	    private func observeExistingActivities() {
150	        let activities = Activity<NinebotChargingActivityAttributes>.activities
151	        store.pruneChargingLiveActivityPushTokens(activeActivityIDs: Set(activities.map(\.id)))
152	        for activity in activities {
153	            observeActivity(activity)
154	        }
155	    }
156	
157	    private func observeActivityUpdates() {
158	        guard activityUpdatesTask == nil else { return }
159	        activityUpdatesTask = Task { [weak self] in
160	            for await activity in Activity<NinebotChargingActivityAttributes>.activityUpdates {
161	                self?.observeActivity(activity)
162	            }
163	        }
164	    }
165	
166	    private func observePushToStartToken() {
167	        guard #available(iOS 17.2, *) else { return }
168	
169	        if let token = Activity<NinebotChargingActivityAttributes>.pushToStartToken {
170	            registerPushToStartToken(token)
171	        }
172	
173	        guard pushToStartTask == nil else { return }
174	        pushToStartTask = Task { [weak self] in
175	            for await tokenData in Activity<NinebotChargingActivityAttributes>.pushToStartTokenUpdates {
176	                self?.registerPushToStartToken(tokenData)
177	            }
178	        }
179	    }
180	
181	    private func registerPushToStartToken(_ data: Data) {
182	        let token = data.hexString
183	        guard !token.isEmpty else { return }
184	        store.saveChargingLiveActivityPushToStartToken(token)
185	        Task {
186	            try? await NinebotPushManager.shared.registerStoredLiveActivityTokensWithServer()
187	        }
188	    }
189	
190	    private func registerActivityPushToken(_ data: Data, activity: Activity<NinebotChargingActivityAttributes>) {
191	        let token = data.hexString
192	        guard !token.isEmpty else { return }
193	        store.saveChargingLiveActivityPushToken(token, activityID: activity.id, vehicleSN: activity.attributes.vehicleSN)
194	        Task {
195	            try? await NinebotPushManager.shared.registerLiveActivityPushTokenWithServer(
196	                token: token,
197	                activityID: activity.id,
198	                vehicleSN: activity.attributes.vehicleSN
199	            )
200	        }
201	    }
202	}
203	
204	private extension Data {
205	    var hexString: String {
206	        map { String(format: "%02x", $0) }.joined()
207	    }
208	}
209	#endif
