1	import Foundation
2	
3	/// Combined power and charging state.
4	///
5	/// The ordering is deliberate and load-bearing: fully charged beats charging,
6	/// and charging beats the power flag. A vehicle at 100% while being ridden
7	/// reports `.fullyCharged`, not `.poweredOn`. That is the existing iOS
8	/// behaviour, and both platforms have to agree on it.
9	enum NinebotPowerStatus: Equatable {
10	    case fullyCharged
11	    case charging
12	    /// `isPoweredOn` is absent. Note this means *the field is missing*, not
13	    /// that the network is down.
14	    case offline
15	    case poweredOn
16	    case poweredOff
17	}
18	
19	/// Whether the vehicle is charging, ignoring the power flag entirely.
20	enum NinebotChargingState: Equatable {
21	    case fullyCharged
22	    case charging
23	    case notCharging
24	    /// `isCharging` is absent.
25	    case unknown
26	}
27	
28	/// Outcome of estimating how long charging has left.
29	enum NinebotChargeEstimate: Equatable {
30	    /// Not charging, so there is nothing to estimate.
31	    case notCharging
32	    /// Charging, but no minute figure is available yet.
33	    case calculating
34	    /// Already at or past the target — full, or past 80%.
35	    case reached
36	    case minutes(Double)
37	
38	    var minuteValue: Double? {
39	        guard case .minutes(let value) = self else { return nil }
40	        return value
41	    }
42	}
43	
44	/// Outcome of projecting a charge estimate onto a wall clock time.
45	enum NinebotChargeClock: Equatable {
46	    /// Not charging, or no minute figure to project.
47	    case unavailable
48	    /// Already at or past the target.
49	    case reached
50	    case at(Date)
51	}
52	
53	extension NinebotVehicleState {
54	
55	    var powerStatus: NinebotPowerStatus {
56	        if isFullyCharged { return .fullyCharged }
57	        if isCharging == true { return .charging }
58	        guard let isPoweredOn else { return .offline }
59	        return isPoweredOn ? .poweredOn : .poweredOff
60	    }
61	
62	    var chargingState: NinebotChargingState {
63	        if isFullyCharged { return .fullyCharged }
64	        guard let isCharging else { return .unknown }
65	        return isCharging ? .charging : .notCharging
