98	    func saveChargingLiveActivityPushToken(_ token: String, activityID: String, vehicleSN: String? = nil) {
99	        defaults.set(token, forKey: chargingLiveActivityPushTokenKey(activityID: activityID))
100	        var records = loadChargingLiveActivityPushTokenRecords()
101	        let cleanedSN = cleanedVehicleSN(vehicleSN) ?? records.first(where: { $0.activityID == activityID })?.vehicleSN
102	        let record = NinebotLiveActivityPushTokenRecord(
103	            activityID: activityID,
104	            token: token,
105	            vehicleSN: cleanedSN,
106	            updatedAt: Date()
107	        )
108	
109	        records.removeAll { existing in
110	            if existing.activityID == activityID {
111	                return true
112	            }
113	            if let cleanedSN, existing.vehicleSN == cleanedSN {
114	                defaults.removeObject(forKey: chargingLiveActivityPushTokenKey(activityID: existing.activityID))
115	                return true
116	            }
117	            return false
118	        }
119	
120	        if cleanedSN == nil {
121	            records.removeAll { existing in
122	                let shouldReplace = existing.vehicleSN == nil
123	                if shouldReplace {
124	                    defaults.removeObject(forKey: chargingLiveActivityPushTokenKey(activityID: existing.activityID))
125	                }
126	                return shouldReplace
127	            }
128	        }
129	
130	        records.append(record)
131	        saveChargingLiveActivityPushTokenRecords(records)
132	    }
