463	    private func loadInterfaceRideRecords(sn: String) -> [NinebotRideRecord] {
464	        guard let data = defaults.data(forKey: interfaceRideKey(sn: sn)),
465	              let records = try? decoder.decode([NinebotRideRecord].self, from: data) else {
466	            return []
467	        }
468	        return sortedInterfaceRideRecords(deduplicatedInterfaceRideRecords(records))
469	    }
