559	    private func saveChargingLiveActivityPushTokenRecords(_ records: [NinebotLiveActivityPushTokenRecord]) {
560	        let sortedRecords = records.sorted { $0.updatedAt > $1.updatedAt }
561	        let recentRecords = Array(sortedRecords.prefix(12))
562	
563	        // Dropping a record has to drop its standalone token key too. Every
564	        // other removal path keeps the two in step; without this the key is
565	        // orphaned, and since prune and removeAll both walk the records list,
566	        // nothing can ever reach it again.
567	        for dropped in sortedRecords.dropFirst(recentRecords.count) {
568	            defaults.removeObject(forKey: chargingLiveActivityPushTokenKey(activityID: dropped.activityID))
569	        }
570	
571	        guard let data = try? encoder.encode(recentRecords) else { return }
572	        defaults.set(data, forKey: Key.chargingLiveActivityPushTokenRecords)
573	    }
