5	enum NinebotBackgroundTaskManager {
6	    static let refreshIdentifier = "com.example.NineBotPlus.refresh"
7	
8	    static func register() {
9	        BGTaskScheduler.shared.register(forTaskWithIdentifier: refreshIdentifier, using: nil) { task in
10	            guard let refreshTask = task as? BGAppRefreshTask else {
11	                task.setTaskCompleted(success: false)
12	                return
13	            }
14	            handle(refreshTask)
15	        }
16	    }
17	
18	    static func scheduleRefresh(after interval: TimeInterval = defaultRefreshInterval) {
19	        let request = BGAppRefreshTaskRequest(identifier: refreshIdentifier)
20	        request.earliestBeginDate = Date().addingTimeInterval(interval)
21	
22	        do {
23	            try BGTaskScheduler.shared.submit(request)
24	        } catch {
25	            // The system may reject duplicate or temporarily unavailable requests.
26	        }
27	    }
28	
29	    private static func handle(_ task: BGAppRefreshTask) {
30	        scheduleRefresh()
31	
32	        let operation = Task {
33	            await refreshDashboard(source: "Background")
34	        }
35	
36	        task.expirationHandler = {
37	            operation.cancel()
38	        }
39	
40	        Task {
41	            let success = await operation.value
42	            task.setTaskCompleted(success: success)
43	        }
44	    }
