46	    @discardableResult
47	    static func refreshDashboard(source: String) async -> Bool {
48	        let startedAt = Date()
49	        let store = NinebotSharedStore()
50	        let cached = store.loadDashboard()
51	        let configuration = store.loadConfiguration() ?? NinebotServerConfiguration(baseURLString: "", bearerToken: "")
52	
53	        guard configuration.isUsable else {
54	            store.saveLastAppRefreshEvent(NinebotRefreshEvent(
55	                source: source,
56	                operation: "后台刷新",
57	                startedAt: startedAt,
58	                endedAt: Date(),
59	                success: false,
60	                message: "未配置数据源"
61	            ))
62	            return false
63	        }
64	
65	        do {
66	            let dashboard = try await NinebotServerClient(configuration: configuration)
67	                .fetchDashboard(selectedSN: cached?.selectedSN)
68	            let archivedDashboard = store.saveDashboard(dashboard)
69	            NinebotChargingLiveActivityManager.sync(with: archivedDashboard)
70	            store.saveLastAppRefreshEvent(NinebotRefreshEvent(
71	                source: source,
72	                operation: "后台刷新",
73	                startedAt: startedAt,
74	                endedAt: Date(),
75	                success: true,
76	                message: archivedDashboard.primaryVehicle?.vehicle.name
77	            ))
78	            WidgetCenter.shared.reloadAllTimelines()
79	            return true
80	        } catch {
81	            store.saveLastError(error.localizedDescription)
82	            store.saveLastAppRefreshEvent(NinebotRefreshEvent(
83	                source: source,
84	                operation: "后台刷新",
85	                startedAt: startedAt,
86	                endedAt: Date(),
87	                success: false,
88	                message: error.localizedDescription
89	            ))
90	            return false
91	        }
92	    }
