94	    private static var defaultRefreshInterval: TimeInterval {
95	        let state = NinebotSharedStore().loadDashboard()?.primaryVehicle?.state
96	        if state?.isCharging == true, state?.isFullyCharged != true {
97	            return 15 * 60
